#: The local copy of an erplora.com account (``base.services.SAAS_USERNAME_PREFIX``).
SAAS_PREFIX = "saas:"


def account_id(username: str):
    """The erplora.com account behind ``saas:<id>``; ``None`` for anyone else (a demo's owner) or an id that is no
    UUID."""
    if not username.startswith(SAAS_PREFIX):
        return None
    try:
        return uuid.UUID(username.removeprefix(SAAS_PREFIX))
    except ValueError:
        return None


def make_hub_users(apps, schema_editor):
    Membership = apps.get_model("base", "Membership")
    if not router.allow_migrate_model(schema_editor.connection.alias, Membership):
        # A hub's own database: control's users and roles are not in it.
        return
